<?php require_once __DIR__.'/../config/db.php'; $pageTitle='Dashboard'; require __DIR__.'/includes/admin_layout_start.php'; $counts=['students'=>0,'tutors'=>0,'pending'=>0,'subjects'=>0]; try{$pdo=db();$counts['students']=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='student'")->fetchColumn();$counts['tutors']=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='tutor' AND is_verified=1 AND is_suspended=0")->fetchColumn();$counts['pending']=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='tutor' AND is_verified=0 AND is_suspended=0 AND rejection_reason IS NULL")->fetchColumn();$counts['subjects']=(int)$pdo->query('SELECT COUNT(*) FROM subjects')->fetchColumn();}catch(Throwable $e){} ?>
